DELETE FROM `creature_text` WHERE `CreatureID` = 101313 AND `GroupID` = 3 AND `ID` = 1 AND `Text` = 'For many long years, the draenei hid from the Burning Legion. All that time, the naaru aided us greatly, sometimes even at the cost of their own lives. Without their help, we surely would have perished.';
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextID`, `MinTimer`, `MaxTimer`, `SpellID`, `comment`) VALUES (101313, 3, 1, 'For many long years, the draenei hid from the Burning Legion. All that time, the naaru aided us greatly, sometimes even at the cost of their own lives. Without their help, we surely would have perished.', 12, 0, 100, 0, 0, 0, 0, 15703, 15703, 0, 'Prophet Velen to Player');
