INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (101313, 3, 1, 'frFR', 'Pendant de très longues années, les draeneï se sont cachés de la Légion ardente. Tout ce temps, les naaru nous ont grandement aidés, parfois même au prix de leur vie. Sans leur aide, c’en aurait sûrement été fini de nous.');
DELETE FROM `creature_text` WHERE `CreatureID` = 101314 AND `GroupID` = 0 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '';
DELETE FROM `creature_text` WHERE `CreatureID` = 101314 AND `GroupID` = 0 AND `ID` = 0 AND `Text` = 'Forgive the secrecy, old habits. My name is Alonsus Faol. In my life I have been head of the church, a mindless servant of the Scourge, and the architect of a secret war. But first and foremost, I have always been, and remain, a priest.';
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextID`, `MinTimer`, `MaxTimer`, `SpellID`, `comment`) VALUES (101314, 0, 0, 'Forgive the secrecy, old habits. My name is Alonsus Faol. In my life I have been head of the church, a mindless servant of the Scourge, and the architect of a secret war. But first and foremost, I have always been, and remain, a priest.', 12, 0, 100, 1, 0, 0, 0, 0, 0, 0, 'Alonsus Faol to Player');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 101314 AND `GroupID` = 0 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (101314, 0, 0, 'frFR', 'Pardonnez tout ce mystère, une vieille habitude. Je m’appelle Alonsus Faol. Au cours de ma vie, j’ai été à la tête de l’Église, serviteur décérébré du Fléau et architecte d’une guerre secrète. Mais avant tout, j’ai toujours été, et je reste, un prêtre.');
DELETE FROM `creature_text` WHERE `CreatureID` = 101314 AND `GroupID` = 1 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '';
DELETE FROM `creature_text` WHERE `CreatureID` = 101314 AND `GroupID` = 1 AND `ID` = 0 AND `Text` = 'The Legion is a threat that cannot be ignored, which is why I have chosen to step out of the shadows once more. I am now gathering all the clergy to devise a common plan against this threat.';
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextID`, `MinTimer`, `MaxTimer`, `SpellID`, `comment`) VALUES (101314, 1, 0, 'The Legion is a threat that cannot be ignored, which is why I have chosen to step out of the shadows once more. I am now gathering all the clergy to devise a common plan against this threat.', 12, 0, 100, 0, 0, 0, 0, 0, 0, 0, 'Alonsus Faol to Player');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 101314 AND `GroupID` = 1 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (101314, 1, 0, 'frFR', 'La Légion est une menace que l’on ne peut ignorer ; c’est pourquoi j’ai décidé de sortir de l’ombre une fois de plus. Je rassemble à présent l’ensemble du clergé afin d’élaborer un plan commun contre cette menace.');
DELETE FROM `creature_text` WHERE `CreatureID` = 101314 AND `GroupID` = 2 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '';
DELETE FROM `creature_text` WHERE `CreatureID` = 101314 AND `GroupID` = 2 AND `ID` = 0 AND `Text` = 'In my design, this council must be led by a truly great priest, one whose deeds have earned renown as a hero not only among our own, but everywhere. I believe you are that hero, but the others will need convincing as well. Are you ready for the trials?';
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextID`, `MinTimer`, `MaxTimer`, `SpellID`, `comment`) VALUES (101314, 2, 0, 'In my design, this council must be led by a truly great priest, one whose deeds have earned renown as a hero not only among our own, but everywhere. I believe you are that hero, but the others will need convincing as well. Are you ready for the trials?', 12, 0, 100, 0, 0, 0, 0, 0, 0, 0, 'Alonsus Faol to Player');
