INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (101314, 2, 0, 'frFR', 'Selon mes plans, ce conseil doit être dirigé par un prêtre véritablement grand, dont les exploits lui ont valu une renommée de héros non seulement parmi les siens, mais partout. Je crois que vous êtes $gce héros:cette héroïne;, mais il faudra encore en convaincre les autres. Êtes-vous $gprêt:prête; à affronter les épreuves ?');
