DELETE FROM `creature_text` WHERE `CreatureID` = 102462 AND `GroupID` = 3 AND `ID` = 1 AND `Text` = 'With the naaru\'s help, we created a place meant to serve as a prison for a Void god, where we could study it, the naaru themselves, and the Twisting Nether. That is the place I wish to show you.';
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextID`, `MinTimer`, `MaxTimer`, `SpellID`, `comment`) VALUES (102462, 3, 1, 'With the naaru\'s help, we created a place meant to serve as a prison for a Void god, where we could study it, the naaru themselves, and the Twisting Nether. That is the place I wish to show you.', 12, 0, 100, 0, 0, 0, 0, 26457, 26457, 0, 'Prophet Velen to Player');
