INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (102462, 3, 1, 'frFR', 'Avec l’aide des naaru, nous avons créé un lieu censé servir de prison à un dieu du Vide, où nous pourrions étudier celui-ci, les naaru eux-mêmes et le Néant distordu. C’est ce lieu que je souhaite vous montrer.');
DELETE FROM `creature_text` WHERE `CreatureID` = 102462 AND `GroupID` = 3 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '';
DELETE FROM `creature_text` WHERE `CreatureID` = 102462 AND `GroupID` = 3 AND `ID` = 2 AND `Text` = 'In times of relative peace, we longed to repay that debt, but we did not know how. Then, to our surprise, one day they came to us with a request. The Light had worked a great miracle: they had managed to imprison a Void god, greatly weakening it.';
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextID`, `MinTimer`, `MaxTimer`, `SpellID`, `comment`) VALUES (102462, 3, 2, 'In times of relative peace, we longed to repay that debt, but we did not know how. Then, to our surprise, one day they came to us with a request. The Light had worked a great miracle: they had managed to imprison a Void god, greatly weakening it.', 12, 0, 100, 0, 0, 0, 0, 10, 10, 0, 'Prophet Velen to Player');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 102462 AND `GroupID` = 3 AND `ID` = 2 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (102462, 3, 2, 'frFR', 'En des temps plus calmes, nous souhaitions ardemment nous acquitter de cette dette, sans savoir comment. Puis, à notre grande surprise, ils sont venus un jour nous demander de l’aide. La Lumière avait accompli un grand miracle : ils étaient parvenus à emprisonner un dieu du Vide, l’affaiblissant considérablement.');
