DELETE FROM `creature_text` WHERE `CreatureID` = 200400 AND `GroupID` = 3 AND `ID` = 0 AND `Text` = 'In the time of the plague, when people had lost hope, my ancestor, a great alchemist, created an artifact meant to restore their faith.';
