INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (200400, 3, 0, 'frFR', 'Au temps de la peste, quand les gens avaient perdu espoir, mon ancêtre, un grand alchimiste, créa un artefact censé leur rendre la foi.');
DELETE FROM `creature_text` WHERE `CreatureID` = 200400 AND `GroupID` = 4 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '';
DELETE FROM `creature_text` WHERE `CreatureID` = 200400 AND `GroupID` = 4 AND `ID` = 0 AND `Text` = 'But as it turned out, he made an error in his calculations, and the artifact only worked at a certain time. It gave the inhabitants of Azeroth a surge of energy for a whole year, which is why it was called the spirit of the new year: a new embodiment of Azeroth\'s life. But now that will not happen. The artifact has been stolen!';
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextID`, `MinTimer`, `MaxTimer`, `SpellID`, `comment`) VALUES (200400, 4, 0, 'But as it turned out, he made an error in his calculations, and the artifact only worked at a certain time. It gave the inhabitants of Azeroth a surge of energy for a whole year, which is why it was called the spirit of the new year: a new embodiment of Azeroth\'s life. But now that will not happen. The artifact has been stolen!', 12, 0, 100, 1, 0, 0, 0, 0, 0, 0, '');
DELETE FROM `creature_text_locale` WHERE `CreatureID` = 200400 AND `GroupID` = 4 AND `ID` = 0 AND `Locale` = 'frFR';
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (200400, 4, 0, 'frFR', 'Mais il s’est trompé dans ses calculs, et l’artefact ne fonctionnait qu’à un moment précis. Il donnait aux habitants d’Azeroth une charge d’énergie pour toute une année, c’est pourquoi on l’a appelé l’esprit du nouvel an : une nouvelle incarnation de la vie d’Azeroth. Mais cette fois, cela n’arrivera pas. L’artefact a été volé !');
DELETE FROM `creature_text` WHERE `CreatureID` = 200400 AND `GroupID` = 5 AND `ID` = 0 AND `BroadcastTextID` = 0 AND HEX(`Text`) = '';
DELETE FROM `creature_text` WHERE `CreatureID` = 200400 AND `GroupID` = 5 AND `ID` = 0 AND `Text` = 'An artifact like that cannot simply be hidden or destroyed. I could build a device to pinpoint its location, but unfortunately I don\'t have the materials to make such an apparatus.';
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextID`, `MinTimer`, `MaxTimer`, `SpellID`, `comment`) VALUES (200400, 5, 0, 'An artifact like that cannot simply be hidden or destroyed. I could build a device to pinpoint its location, but unfortunately I don\'t have the materials to make such an apparatus.', 12, 0, 100, 1, 0, 0, 0, 0, 0, 0, '');
