INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES (200400, 5, 0, 'frFR', 'Un tel artefact ne se cache ni ne se détruit si facilement. Je pourrais fabriquer un appareil capable de le localiser, mais hélas, je n’ai pas les matériaux nécessaires.');
